// Live topbar amber balance display
window.amberUnsubscribe = null;
window._amberSubscribeTopbar = function() {
    if (!auth.currentUser) return;
    if (window.amberUnsubscribe) { window.amberUnsubscribe(); window.amberUnsubscribe = null; }
    window.amberUnsubscribe = onSnapshot(doc(db, 'profiles', auth.currentUser.uid), (snap) => {
        const amber = snap.exists() ? (snap.data().amber || 0) : 0;
        const badge = document.getElementById('topbar-amber-badge');
        const val = document.getElementById('topbar-amber-value');
        if (val) val.textContent = amber.toLocaleString();
        if (badge) badge.style.display = 'flex';
    });
};

// Award amber to the current user
async function _awardAmber(amount, reason) {
    if (!auth.currentUser || amount <= 0) return;
    const uid = auth.currentUser.uid;
    try {
        await updateDoc(doc(db, 'profiles', uid), { amber: increment(amount) });
        addDoc(collection(db, 'amber_log'), { uid, amount, reason, timestamp: new Date() }).catch(() => {});
    } catch(e) {}
}

// Award amber to any uid — used for likes received by post author
async function _awardAmberToUser(uid, amount, reason) {
    if (!uid || amount <= 0) return;
    await updateDoc(doc(db, 'profiles', uid), { amber: increment(amount) });
    addDoc(collection(db, 'amber_log'), { uid, amount, reason, timestamp: new Date() }).catch(() => {});
}

// Award amber for a daily-capped action (e.g. games) — fires once per key per day
function _awardAmberDaily(key, amount) {
    if (!auth.currentUser) return;
    const today = new Date().toISOString().split('T')[0];
    const storageKey = `weebee_amber_${key}_${today}`;
    if (localStorage.getItem(storageKey)) return;
    localStorage.setItem(storageKey, '1');
    _awardAmber(amount, key).catch(() => {});
}

// One-time bonus for a user's very first review (quick or in-depth) —
// guarded by a profile flag so deleting/re-adding a review can't re-trigger it.
async function _awardFirstReviewBonus() {
    if (!auth.currentUser) return;
    const uid = auth.currentUser.uid;
    try {
        const pd = await getDoc(doc(db, 'profiles', uid));
        if (pd.exists() && pd.data().firstReviewBonusGiven) return;
        await setDoc(doc(db, 'profiles', uid), { firstReviewBonusGiven: true }, { merge: true });
        await _awardAmber(500, 'review:first');
    } catch(e) {}
}

// Award 1 amber for an interaction (like/comment given) — max 10/day combined
function _awardAmberInteraction() {
    if (!auth.currentUser) return;
    const today = new Date().toISOString().split('T')[0];
    const key = `weebee_amber_interactions_${today}`;
    const count = parseInt(localStorage.getItem(key) || '0');
    if (count >= 10) return;
    localStorage.setItem(key, count + 1);
    _awardAmber(1, 'interaction').catch(() => {});
}

// Tracks the "reacted to N posts" Social achievements — call when a user
// adds a like/dislike/agree/etc. to any post (not when removing one).
function _recordReactionGiven() {
    if (!auth.currentUser) return;
    setDoc(doc(db, "profiles", auth.currentUser.uid), { reactionCount: increment(1) }, { merge: true }).then(() =>
        getDoc(doc(db, "profiles", auth.currentUser.uid)).then(pd => {
            window.awardAchievements(window.getEarnedIds('react', pd.exists() ? (pd.data().reactionCount || 1) : 1)).catch(() => {});
        })
    ).catch(() => {});
}
