window.renderBuiltinBracketTemplates = function() {
    const el = document.getElementById('bracket-builtin-grid');
    if (!el) return;
    const templates = window._getBracketTemplates();
    el.innerHTML = templates.map(t => {
        const imgs = t.items.slice(0, 4).map(it => `<img src="${it.image}" style="flex:1;min-width:0;object-fit:cover;height:52px;" onerror="this.style.display='none'">`).join('');
        return `<div onclick="window.useBracketTemplate('${t.id}',true)" style="background:var(--bg-gray-darker);border-radius:10px;overflow:hidden;cursor:pointer;border:2px solid transparent;transition:border-color .15s;" onmouseover="this.style.borderColor='var(--accent-yellow)'" onmouseout="this.style.borderColor='transparent'">
            <div style="display:flex;height:52px;overflow:hidden;">${imgs}</div>
            <div style="padding:8px 10px;">
                <div style="font-weight:700;font-size:13px;line-height:1.3;">${t.title}</div>
                <div style="font-size:11px;color:var(--accent-yellow);margin-top:2px;font-weight:600;">${t.items.length} chars · WeeBee ⭐</div>
            </div>
        </div>`;
    }).join('');
};

window._bracketCommunityTemplates = [];

window.loadBracketCommunityTemplates = async function() {
    const el = document.getElementById('bracket-community-grid');
    if (!el) return;
    el.innerHTML = '<div style="color:var(--text-muted);font-size:13px;padding:8px;text-align:center;">Loading...</div>';
    try {
        const snap = await getDocs(query(collection(db, 'bracket_templates'), orderBy('timestamp', 'desc'), limit(50)));
        window._bracketCommunityTemplates = snap.docs.map(d => ({ id: d.id, ...d.data() }));
        window.filterBracketTemplates(document.getElementById('bracket-template-search')?.value || '');
    } catch(e) {
        window._bracketCommunityTemplates = [];
        window.filterBracketTemplates('');
    }
};

window.filterBracketTemplates = function(q) {
    const el = document.getElementById('bracket-community-grid');
    if (!el) return;
    const lq = q.toLowerCase().trim();
    const list = lq ? window._bracketCommunityTemplates.filter(t => t.title?.toLowerCase().includes(lq) || t.authorName?.toLowerCase().includes(lq)) : window._bracketCommunityTemplates;
    if (!list.length) {
        el.innerHTML = '<div style="color:var(--text-muted);font-size:13px;padding:8px;text-align:center;">No community templates yet — create one!</div>';
        return;
    }
    el.innerHTML = list.map(t => {
        const imgs = (t.items||[]).slice(0, 4).map(it => `<img src="${it.image}" style="width:30px;height:42px;object-fit:cover;border-radius:4px;flex-shrink:0;" onerror="this.style.display='none'">`).join('');
        const ago = t.timestamp?.toDate ? formatTimeAgo(t.timestamp.toDate()) : '';
        return `<div onclick="window.useBracketTemplate('${t.id}',false)" style="display:flex;align-items:center;gap:10px;background:var(--bg-gray-darker);border-radius:10px;padding:10px;cursor:pointer;border:2px solid transparent;transition:border-color .15s;" onmouseover="this.style.borderColor='var(--accent-yellow)'" onmouseout="this.style.borderColor='transparent'">
            <div style="display:flex;gap:3px;flex-shrink:0;">${imgs}</div>
            <div style="flex:1;min-width:0;">
                <div style="font-weight:700;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${t.title}</div>
                <div style="font-size:11px;color:var(--text-muted);margin-top:2px;">${(t.items||[]).length} chars · ${t.authorName||'Anonymous'} · ${ago}</div>
            </div>
        </div>`;
    }).join('');
};

window.useBracketTemplate = function(id, isBuiltIn) {
    const t = isBuiltIn
        ? window._getBracketTemplates().find(x => x.id === id)
        : window._bracketCommunityTemplates.find(x => x.id === id);
    if (!t) return;
    document.getElementById('bracket-title-input').value = t.title;
    window._bracketAnimePool = (t.items || []).map(item => ({ ...item }));
    window._renderBracketPool();
    window.switchBracketTab({ currentTarget: document.getElementById('bracket-tab-btn-custom') }, 'custom');
};

window.createBracket = async function() {
    if (!auth.currentUser) return window.openAuthModal();
    const title = document.getElementById('bracket-title-input').value.trim();
    if (!title) return alert('Please enter a bracket title.');
    const pool = window._bracketAnimePool;
    if (pool.length < 4) return alert('Add at least 4 characters.');
    if ((pool.length & (pool.length - 1)) !== 0) return alert('Bracket requires exactly 4, 8, or 16 characters.');
    const pd = await getDoc(doc(db, 'profiles', auth.currentUser.uid)).catch(() => null);
    const displayName = pd?.data()?.displayName || auth.currentUser.displayName;
    const avatar = pd?.data()?.avatar || auth.currentUser.photoURL || `https://api.dicebear.com/9.x/initials/svg?seed=${encodeURIComponent(displayName)}&backgroundColor=ffc107&fontColor=333333`;
    const shuffled = [...pool].sort(() => Math.random() - 0.5);
    const round0 = [];
    for (let i = 0; i < shuffled.length; i += 2) round0.push({ animeA: shuffled[i], animeB: shuffled[i+1] });
    const totalRounds = Math.ceil(Math.log2(pool.length));
    const saveAsTemplate = document.getElementById('bracket-save-template')?.checked;
    try {
        const data = { uid: auth.currentUser.uid, authorName: displayName, authorAvatar: avatar, title, rounds: { "0": round0 }, totalRounds, currentRound: 0, votes: {}, status: 'voting', champion: null, timestamp: new Date() };
        const ref = await addDoc(collection(db, 'brackets'), data);
        if (saveAsTemplate) {
            const tmplData = { uid: auth.currentUser.uid, authorName: displayName, authorAvatar: avatar, title, items: pool.map(p => ({ title: p.title, image: p.image, mal_id: p.mal_id })), timestamp: serverTimestamp(), likes: [], dislikes: [] };
            const tmplRef = await addDoc(collection(db, 'bracket_templates'), tmplData);
            window._bracketCommunityTemplates.unshift({ id: tmplRef.id, ...tmplData, timestamp: { toDate: () => new Date() } });
        }
        document.getElementById('bracket-title-input').value = '';
        document.getElementById('bracket-save-template').checked = false;
        window._bracketAnimePool = [];
        window._renderBracketPool();
        window.switchBracketTab({ currentTarget: document.getElementById('bracket-tab-btn-templates') }, 'templates');
        window._bracketsList.unshift({ id: ref.id, ...data, timestamp: { toDate: () => new Date() } });
        window._renderBracketsFeed();
        window.openBracketPlayModal(ref.id);
    } catch(e) { console.error('Bracket create failed:', e); alert('Failed to create bracket: ' + e.message); }
};

window.voteInBracket = async function(bracketId, round, matchIdx, side) {
    if (!auth.currentUser) return window.openAuthModal();
    delete window._bracketPendingVote[bracketId];
    const uid = auth.currentUser.uid;
    const b = window._bracketsList.find(x => x.id === bracketId);
    if (!b) return;
    const keyA = `${round}_${matchIdx}_A`, keyB = `${round}_${matchIdx}_B`;
    if ((b.votes?.[keyA]||[]).includes(uid) || (b.votes?.[keyB]||[]).includes(uid)) return;
    if (!b.votes) b.votes = {};
    const key = side === 'A' ? keyA : keyB;
    b.votes[key] = [...(b.votes[key]||[]), uid];
    const totalMatchups = (b.rounds?.[String(round)] || []).length;
    if (matchIdx < totalMatchups - 1) {
        window._bracketMatchupIdx[bracketId] = matchIdx + 1;
    }
    window._renderBracketsFeed();
    try {
        await updateDoc(doc(db, 'brackets', bracketId), { [`votes.${key}`]: arrayUnion(uid) });
    } catch(e) {
        b.votes[key] = b.votes[key].filter(x => x !== uid);
        window._renderBracketsFeed();
        alert('Failed to submit vote.');
    }
};

window.advanceBracket = async function(bracketId) {
    if (!auth.currentUser) return;
    const b = window._bracketsList.find(x => x.id === bracketId);
    if (!b) return;
    const round = b.currentRound || 0;
    const matchups = b.rounds[String(round)];
    const winners = matchups.map((m, mi) => {
        const votesA = (b.votes?.[`${round}_${mi}_A`]||[]).length;
        const votesB = (b.votes?.[`${round}_${mi}_B`]||[]).length;
        return votesA >= votesB ? m.animeA : m.animeB;
    });
    if (winners.length === 1) {
        b.champion = winners[0];
        b.status = 'completed';
        try {
            await updateDoc(doc(db, 'brackets', bracketId), { champion: winners[0], status: 'completed' });
            window._renderBracketsFeed();
        } catch(e) { alert('Failed to advance: ' + e.message); }
        return;
    }
    const nextRound = [];
    for (let i = 0; i < winners.length; i += 2) {
        if (winners[i] && winners[i+1]) nextRound.push({ animeA: winners[i], animeB: winners[i+1] });
    }
    const nextIdx = round + 1;
    if (!b.rounds) b.rounds = {};
    b.rounds[String(nextIdx)] = nextRound;
    b.currentRound = nextIdx;
    window._bracketMatchupIdx[bracketId] = 0;
    try {
        await updateDoc(doc(db, 'brackets', bracketId), { [`rounds.${nextIdx}`]: nextRound, currentRound: nextIdx });
        window._renderBracketsFeed();
    } catch(e) { alert('Failed to advance: ' + e.message); }
};

window.deleteBracket = async function(id) {
    if (!auth.currentUser) return;
    if (!confirm('Delete this bracket?')) return;
    try {
        await deleteDoc(doc(db, 'brackets', id));
        window._bracketsList = window._bracketsList.filter(b => b.id !== id);
        window._renderBracketsFeed();
    } catch(e) { alert('Failed to delete.'); }
};

// --- PATCH NOTES ---
window.currentPatchNotes = [];

window.loadPatchNotes = async function() {
    try {
        const snap = await getDocs(query(collection(db, "patch_notes"), orderBy("timestamp", "desc"), limit(20)));
        window.currentPatchNotes = snap.docs.map(d => ({ id: d.id, ...d.data() }));
        const feed = document.getElementById('patch-notes-feed');
        const section = document.getElementById('patch-notes-section');
        if (!feed || !section) return;
        if (snap.empty) { section.style.display = 'none'; return; }
        section.style.display = 'block';
        feed.style.gridTemplateColumns = 'repeat(auto-fill, minmax(220px, 1fr))';

        const VISIBLE = 4;
        const renderCard = (p, i) => `
            <div class="news-card${i >= VISIBLE ? ' pn-hidden' : ''}" onclick="openPatchNoteModal(${i})" style="cursor:pointer; position:relative;${i >= VISIBLE ? 'display:none;' : ''}">
                <div style="background:var(--accent-yellow); height:6px; border-radius:10px 10px 0 0;"></div>
                <div class="news-content">
                    ${i === 0 ? '<div style="display:inline-block;background:var(--accent-yellow);color:#111;font-size:10px;font-weight:800;padding:2px 10px;border-radius:20px;letter-spacing:0.5px;margin-bottom:10px;">✦ LATEST</div>' : ''}
                    <div style="display:flex; align-items:center; gap:8px; margin-bottom:8px;">
                        <img src="${p.authorAvatar || ''}" style="width:28px; height:28px; border-radius:50%; object-fit:cover;" onerror="this.style.display='none'">
                        <div>
                            <div style="font-size:11px; font-weight:700; color:var(--accent-yellow);">WeeBee Update</div>
                            <div style="font-size:10px; color:var(--text-muted);">${p.authorName || 'WeeBee'}</div>
                        </div>
                    </div>
                    <h3 style="font-size:14px; font-weight:700; margin-bottom:6px; line-height:1.4;">${p.title}</h3>
                    <p style="font-size:12px; color:var(--text-muted); display:-webkit-box; -webkit-line-clamp:3; -webkit-box-orient:vertical; overflow:hidden; line-height:1.5;">${p.body.replace(/\n/g, ' ')}</p>
                    <div class="news-footer">
                        <span style="font-size:11px; color:var(--text-muted);">${p.timestamp?.toDate ? new Date(p.timestamp.toDate()).toLocaleDateString('en-US', {month:'short',day:'numeric',year:'numeric'}) : ''}</span>
                        <span class="news-link" style="font-size:12px;">Read More</span>
                    </div>
                </div>
            </div>`;

        feed.innerHTML = window.currentPatchNotes.map(renderCard).join('');

        // Show more button spanning full grid width
        if (window.currentPatchNotes.length > VISIBLE) {
            const remaining = window.currentPatchNotes.length - VISIBLE;
            feed.insertAdjacentHTML('beforeend', `
                <div id="pn-show-more" style="grid-column:1/-1; text-align:center; padding-top:4px;">
                    <button onclick="window.expandPatchNotes()" class="action-btn" style="background:var(--bg-gray-darker);color:var(--text-dark);">
                        <span class="material-symbols-outlined" style="font-size:16px;">expand_more</span> Show ${remaining} older update${remaining !== 1 ? 's' : ''}
                    </button>
                </div>`);
        }
        window.checkPatchNoteBadge();
    } catch(e) { console.error('loadPatchNotes', e); }
};

window.expandPatchNotes = function() {
    document.querySelectorAll('.pn-hidden').forEach(el => el.style.display = '');
    const btn = document.getElementById('pn-show-more');
    if (btn) btn.style.display = 'none';
};

window.openPatchNoteModal = function(index) {
    const p = window.currentPatchNotes[index];
    if (!p) return;
    document.getElementById('article-reader-img').style.display = 'none';
    document.getElementById('article-reader-anime').innerText = 'WeeBee Patch Notes';
    document.getElementById('article-reader-anime').onclick = null;
    document.getElementById('article-reader-date').innerText = p.timestamp?.toDate ? new Date(p.timestamp.toDate()).toLocaleDateString('en-US', { year:'numeric', month:'long', day:'numeric' }) : '';
    document.getElementById('article-reader-title').innerText = p.title;
    const body = document.getElementById('article-reader-body');
    body.style.whiteSpace = 'pre-line';
    body.innerText = p.body;
    document.getElementById('article-reader-link').style.display = 'none';
    window.currentArticleReactionId = p.id;
    const uid = auth.currentUser?.uid;
    const likes = p.likes || [];
    const dislikes = p.dislikes || [];
    const reactionsEl = document.getElementById('article-reader-reactions');
    reactionsEl.style.display = 'flex';
    document.getElementById('article-like-count').innerText = likes.length;
    document.getElementById('article-dislike-count').innerText = dislikes.length;
    document.getElementById('article-like-btn').style.color = uid && likes.includes(uid) ? 'var(--accent-yellow)' : 'var(--text-dark)';
    document.getElementById('article-dislike-btn').style.color = uid && dislikes.includes(uid) ? '#FF5252' : 'var(--text-dark)';
    window.closeAllModals();
    document.getElementById('article-reader-modal').style.display = 'flex';
};

window.submitPatchNote = async function() {
    if (!auth.currentUser || !window.isAdmin) return;
    const title = document.getElementById('patch-notes-title').value.trim();
    const body = document.getElementById('patch-notes-body').value.trim();
    if (!title || !body) return alert('Please fill in both the title and body.');
    try {
        const myAvatar = auth.currentUser.photoURL || `https://api.dicebear.com/9.x/initials/svg?seed=${encodeURIComponent(auth.currentUser.displayName)}&backgroundColor=ffc107&fontColor=333333`;
        await addDoc(collection(db, "patch_notes"), {
            title, body,
            authorName: auth.currentUser.displayName,
            authorAvatar: myAvatar,
            timestamp: new Date()
        });
        document.getElementById('patch-notes-title').value = '';
        document.getElementById('patch-notes-body').value = '';
        await window.loadPatchNotes();
        alert('Patch notes posted!');
    } catch(e) { alert('Failed to post.'); console.error(e); }
};

window.toggleArticleReaction = async function(type) {
    if (!auth.currentUser) return window.openAuthModal();
    const id = window.currentArticleReactionId;
    if (!id) return;
    const uid = auth.currentUser.uid;
    const pRef = doc(db, "patch_notes", id);
    const pSnap = await getDoc(pRef);
    if (!pSnap.exists()) return;
    let likes = [...(pSnap.data().likes || [])];
    let dislikes = [...(pSnap.data().dislikes || [])];
    let addedReaction = false;
    if (type === 'like') {
        if (likes.includes(uid)) { likes = likes.filter(u => u !== uid); }
        else { likes = [...likes.filter(u => u !== uid), uid]; addedReaction = true; }
        dislikes = dislikes.filter(u => u !== uid);
    } else {
        if (dislikes.includes(uid)) { dislikes = dislikes.filter(u => u !== uid); }
        else { dislikes = [...dislikes.filter(u => u !== uid), uid]; addedReaction = true; }
        likes = likes.filter(u => u !== uid);
    }
    await updateDoc(pRef, { likes, dislikes });
    if (addedReaction) _recordReactionGiven();
    document.getElementById('article-like-count').innerText = likes.length;
    document.getElementById('article-dislike-count').innerText = dislikes.length;
    document.getElementById('article-like-btn').style.color = likes.includes(uid) ? 'var(--accent-yellow)' : 'var(--text-dark)';
    document.getElementById('article-dislike-btn').style.color = dislikes.includes(uid) ? '#FF5252' : 'var(--text-dark)';
    const cached = window.currentPatchNotes.find(p => p.id === id);
    if (cached) { cached.likes = likes; cached.dislikes = dislikes; }
};

window.checkPatchNoteBadge = function() {
    const badge = document.getElementById('news-badge');
    if (!badge || window.currentPatchNotes.length === 0) return;
    const lastRead = parseInt(localStorage.getItem('weebee-last-read-patch') || '0');
    const latest = window.currentPatchNotes[0]?.timestamp?.toDate
        ? window.currentPatchNotes[0].timestamp.toDate().getTime()
        : 0;
    const unread = window.currentPatchNotes.filter(p => {
        const t = p.timestamp?.toDate ? p.timestamp.toDate().getTime() : 0;
        return t > lastRead;
    }).length;
    if (unread > 0) { badge.innerText = unread; badge.style.display = 'flex'; }
    else { badge.style.display = 'none'; }
};

window.clearPatchNoteBadge = function() {
    localStorage.setItem('weebee-last-read-patch', Date.now().toString());
    const badge = document.getElementById('news-badge');
    if (badge) badge.style.display = 'none';
};

